package com.franco.desco.adapter.out.sqlserver.visit;import com.franco.desco.adapter.out.sqlserver.shared.*;import com.franco.desco.application.visit.*;import com.franco.desco.application.visit.port.out.VisitPersistencePort;import com.franco.desco.application.shared.*;import com.franco.desco.application.shared.pagination.PageResult;import com.franco.desco.domain.visit.VisitModels;import org.springframework.jdbc.core.simple.SimpleJdbcCall;import org.springframework.stereotype.Component;import java.util.*;
@Component public class VisitSqlServerAdapter implements VisitPersistencePort{private final SqlServerPaExecutor e;private final PaPayloadFactory pf;private final SimpleJdbcCall list,get,start,update,finish,annul;public VisitSqlServerAdapter(SqlServerPaFactory f,SqlServerPaExecutor e,PaPayloadFactory pf){this.e=e;this.pf=pf;list=f.callWithResultSets("campo","PA_VisitaTecnica_Sel_Listado","items");get=f.callWithResultSets("campo","PA_VisitaTecnica_Sel_DetalleCompleto","header","evaluations","files");start=f.call("campo","PA_VisitaTecnica_Ins_Iniciar");update=f.call("campo","PA_VisitaTecnica_Upd_Registro");finish=f.call("campo","PA_VisitaTecnica_Upd_Finalizar");annul=f.call("campo","PA_VisitaTecnica_Upd_Anular");}
 public PersistenceResult<PageResult<VisitModels.Summary>>list(VisitCommands.ListVisits c,SessionIdentity i,RequestMetadata m){var pg=c.page();var f=pg.filtros();var payload=pf.forQuery(i,m,Map.of("filtros",map("pagina",pg.pagina(),"tamanoPagina",pg.tamanio(),"predioId",f==null?null:f.predioId(),"empleadoId",f==null?null:f.empleadoId(),"salidaCampoId",f==null?null:f.salidaCampoId(),"estadoProceso",f==null?null:f.estadoProceso(),"fechaDesde",f==null?null:f.fechaDesde(),"fechaHasta",f==null?null:f.fechaHasta(),"buscar",f==null?null:f.buscar())));var out=e.executeJson(list,payload);return PaAdapterSupport.page(out,rows(out,"items"),pg.pagina(),pg.tamanio(),this::summary,"No se pudieron consultar las visitas.");}
 public PersistenceResult<VisitModels.Detail>get(VisitCommands.Get c,SessionIdentity i,RequestMetadata m){var out=e.executeJson(get,pf.forQuery(i,m,Map.of("visita",Map.of("visitaTecnicaId",c.visitaTecnicaId()))));if(!PaAdapterSupport.success(out))return PersistenceResult.error(PaAdapterSupport.message(out,"No se pudo consultar la visita."));var h=one(out,"header");if(h==null)return PersistenceResult.error("La visita seleccionada no está disponible.");var s=summary(h);return PersistenceResult.ok(PaAdapterSupport.message(out,"Visita consultada correctamente."),new VisitModels.Detail(s,SqlValues.string(h,"resumen"),SqlValues.string(h,"recomendaciones"),rows(out,"evaluations").stream().map(this::evaluation).toList(),rows(out,"files").stream().map(this::file).toList()));}
 public PersistenceResult<Long>start(VisitCommands.Start c,SessionIdentity i,RequestMetadata m){var out=e.executeJson(start,pf.forWrite(i,m,c,Map.of("visita",map("salidaParticipanteId",c.salidaParticipanteId(),"predioId",c.predioId(),"fechaHoraInicio",c.fechaHoraInicio(),"latitud",c.latitud(),"longitud",c.longitud(),"objetivo",c.objetivo()))));return PaAdapterSupport.result(out,SqlValues.longValue(out,"nVisitaTecnicaId"),"No se pudo iniciar la visita.");}
 public PersistenceResult<Void>update(VisitCommands.Update c,SessionIdentity i,RequestMetadata m){return mut(update,i,m,c,map("visitaTecnicaId",c.visitaTecnicaId(),"objetivo",c.objetivo(),"resumen",c.resumen(),"recomendaciones",c.recomendaciones()),"No se pudo actualizar la visita.");}public PersistenceResult<Void>finish(VisitCommands.Finish c,SessionIdentity i,RequestMetadata m){return mut(finish,i,m,c,map("visitaTecnicaId",c.visitaTecnicaId(),"fechaHoraFin",c.fechaHoraFin(),"resumen",c.resumen(),"recomendaciones",c.recomendaciones()),"No se pudo finalizar la visita.");}public PersistenceResult<Void>annul(VisitCommands.Annul c,SessionIdentity i,RequestMetadata m){return mut(annul,i,m,c,map("visitaTecnicaId",c.visitaTecnicaId(),"motivo",c.motivo(),"fechaHoraFin",c.fechaHoraFin()),"No se pudo anular la visita.");}
 private PersistenceResult<Void>mut(SimpleJdbcCall call,SessionIdentity i,RequestMetadata m,Object body,Map<String,Object>v,String f){return PaAdapterSupport.result(e.executeJson(call,pf.forWrite(i,m,body,Map.of("visita",v))),null,f);}private VisitModels.Summary summary(Map<String,Object>r){return new VisitModels.Summary(SqlValues.longValue(r,"visitaTecnicaId"),SqlValues.longValue(r,"salidaParticipanteId"),SqlValues.longValue(r,"salidaCampoId"),SqlValues.longValue(r,"empleadoId"),SqlValues.string(r,"tecnico"),SqlValues.longValue(r,"predioId"),SqlValues.string(r,"codigoPredio"),SqlValues.string(r,"predio"),SqlValues.instant(r,"fechaHoraInicio"),SqlValues.instant(r,"fechaHoraFin"),SqlValues.string(r,"objetivo"),SqlValues.string(r,"estadoProceso"),SqlValues.decimal(r,"latitud"),SqlValues.decimal(r,"longitud"));}private VisitModels.Evaluation evaluation(Map<String,Object>r){return new VisitModels.Evaluation(SqlValues.longValue(r,"evaluacionAgronomicaId"),SqlValues.longValue(r,"parcelaCultivoId"),SqlValues.intValue(r,"tipoEvaluacionId"),SqlValues.string(r,"codigoTipoEvaluacion"),SqlValues.string(r,"tipoEvaluacion"),SqlValues.instant(r,"fechaHora"),SqlValues.string(r,"resultado"),SqlValues.string(r,"observacion"),SqlValues.decimal(r,"porcentajeMateriaSeca"),SqlValues.intValue(r,"numeroMuestras"));}private VisitModels.File file(Map<String,Object>r){return new VisitModels.File(SqlValues.longValue(r,"archivoId"),SqlValues.string(r,"nombreOriginal"),SqlValues.string(r,"mimeType"),SqlValues.longValue(r,"tamanoBytes"),SqlValues.string(r,"secureUrl"),SqlValues.string(r,"categoria"),SqlValues.string(r,"origenCaptura"),SqlValues.instant(r,"fechaCarga"));}private List<Map<String,Object>>rows(Map<String,Object>o,String k){return new PaResultSets(o).rows(k);}private Map<String,Object>one(Map<String,Object>o,String k){return new PaResultSets(o).one(k).orElse(null);}private static Map<String,Object>map(Object...v){Map<String,Object>m=new LinkedHashMap<>();for(int n=0;n<v.length;n+=2)if(v[n+1]!=null)m.put((String)v[n],v[n+1]);return m;}}
